"use strict";
const fs = require("fs");
const path = require("path");
const lib = require("./lib");
const below = (file) => path.relative(__dirname, file);
exports.where = function where() {
  return [
    path.basename(__filename),
    __dirname === path.dirname(__filename),
    below(module.filename),
    module.id === __filename,
    module.children.map((child) => below(child.filename)).join(","),
    Object.keys(require.cache)
      .filter((file) => file.startsWith(__dirname + path.sep))
      .map(below)
      .sort()
      .join(","),
    lib.where(__dirname),
    fs.readFileSync(path.join(__dirname, "data.txt"), "utf8").trim(),
  ].join(" ");
};
